func adminHeapChartJSON(history []models.RuntimeSample) string {
	data := adminSparklineData{Name: "Live heap", Suffix: " MiB"}
	for _, sample := range history {
		data.Times = append(data.Times, sample.At.Unix())
		data.Values = append(data.Values, float64(sample.LiveHeapBytes)/(1<<20))
	}

	return adminSparklineJSON(data)
}

