// adminHeapChange is the live heap's change over the history, e.g. a heap that
// went from 7.0 MiB to 7.4 MiB -> +0.4 MiB.
func adminHeapChange(history []models.RuntimeSample) string {
	first, last := history[0].LiveHeapBytes, history[len(history)-1].LiveHeapBytes
	if last >= first {
		return "+" + adminBytes(last-first)
	}

	return "-" + adminBytes(first-last)
}

// adminGoroutineChange is the goroutine count's change over the history, e.g.
// 37 to 40 -> +3.
func adminGoroutineChange(history []models.RuntimeSample) string {
	return fmt.Sprintf("%+d", history[len(history)-1].Goroutines-history[0].Goroutines)
}

